package com.pulsefit.attendanceservice; import com.pulsefit.attendanceservice.entity.Attendance; import com.pulsefit.attendanceservice.repo.AttendanceRepository; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*; import java.time.LocalDateTime; @Configuration public class DataInitializer { @Bean CommandLineRunner seed(AttendanceRepository r){return args->{if(r.count()==0){r.save(make(1L,"Hyderabad Central",2));r.save(make(2L,"Vijayawada",4));r.save(make(3L,"Hyderabad Central",8));}};} private Attendance make(Long m,String f,int h){Attendance a=new Attendance();a.memberId=m;a.facility=f;a.checkInTime=LocalDateTime.now().minusHours(h);a.status="CHECKED_OUT";a.checkOutTime=a.checkInTime.plusHours(1);return a;} }
